package com.bonbio.controller;
import com.bonbio.dto.Dtos.*; import com.bonbio.service.ClientService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/clients") public class ClientController {private final ClientService s; public ClientController(ClientService s){this.s=s;} @GetMapping public List<ClientResponse> all(){return s.all();} @GetMapping("/{id}") public ClientResponse one(@PathVariable Long id){return s.one(id);} @PostMapping public ClientResponse add(@Valid @RequestBody ClientRequest r){return s.save(null,r);} @PutMapping("/{id}") public ClientResponse edit(@PathVariable Long id,@Valid @RequestBody ClientRequest r){return s.save(id,r);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){s.delete(id);} }
